# -*- coding: utf-8 -*-
"""برومبتات الصور القصصية للوحدة U11 «قضايا التكامل» (يولّدها صاحب المشروع). يكتب:
art-sources/U11/prompts/prompts-final-imagegen.json و art-sources/U11/prompts/الصور-القصصية-للنسخ.md
الاستعمال: python3 art-sources/U11/sources/prompts_u11.py
"""
from pathlib import Path
import json, importlib.util

HERE = Path(__file__).resolve().parent
OUT = HERE.parent / 'prompts'
_sp = importlib.util.spec_from_file_location('p10', HERE.parent.parent / 'U10' / 'sources' / 'prompts_u10.py'); p10 = importlib.util.module_from_spec(_sp); _sp.loader.exec_module(p10)
STYLE, BOY, GIRL, LAM, END, RB, RG, RL = p10.STYLE, p10.BOY, p10.GIRL, p10.LAM, p10.END, p10.RB, p10.RG, p10.RL
NEG = p10.NEG + ", cigarettes, lit cigarette, smoke from a mouth, brand names, packs of cigarettes, diseased organs, skulls"

def title(kid, who, pr):
    return {
      'L01': f"Title scene for a lesson about how the whole body works together as a team while running. {kid} runs happily across a sunny school yard, cheeks a little pink, a few small sweat drops on {who} forehead. Around the child float five soft round see-through windows connected by gentle dotted golden lines like a team: the brain with a tiny spark, the two pink lungs, a simple realistic heart (cone-shaped, NOT a ♥ symbol), a patch of skin with tiny sweat droplets, and the two bean-shaped kidneys with a water drop. {LAM} runs beside the child holding a small water bottle. MUST: the heart looks like a real simple heart, not a valentine symbol; organs are simple and friendly, not gory; no text or numbers.",
      'L02': f"Title scene for a lesson about how smoke harms the whole body, calm and hopeful, with NO cigarette anywhere. {kid} stands in a green park taking a deep happy breath of fresh air, eyes closed, arms open; a soft see-through window on {who} chest shows two healthy pink lungs linked by a thin red line to a simple realistic heart and up to the brain. Far away behind a tree a small faint grey cloud drifts away and fades. {LAM} stands beside the child holding up an open glove in a gentle 'no thanks' gesture toward the grey cloud. MUST: no cigarettes, no smokers, no smoke near the child; the heart is not a ♥ symbol; no text.",
      'L04': f"Title scene for a lesson about judging health claims. {kid} sits at a home table holding a phone; above the phone floats a large message bubble with only wavy lines; {LAM} leans in and looks through its lens at the bubble. Around them float four soft round icons: a person silhouette (who said it?), a second magnifying glass (how did they know?), a balance scale with two small identical groups of figures on its two pans (a fair comparison), and a short stack of books with a doctor's stethoscope (what do experts say?). MUST: no text, no letters, no question marks; the phone screen shows only wavy lines.",
    }

def items():
    P = []
    def add(name, refs, prompt, check, lesson=None):
        P.append({'name': name, 'lesson': lesson or name[:7], 'refs': refs, 'prompt': STYLE + '\n\n' + prompt + END, 'negative': NEG, 'check': check})
    tb, tg = title(BOY, 'his', 'he'), title(GIRL, 'her', 'she')
    chk_title = {'L01': 'خمس نوافذ: الدماغ والرئتان والقلب (لا رمز ♥) والجلد بالعرق والكليتان، تربطها خطوط ذهبية؛ قطرات عرق صغيرة؛ بلا كتابة.',
                 'L02': 'لا سجائر ولا مدخّنين؛ رئتان سليمتان وقلب حقيقي الشكل؛ سحابة رمادية بعيدة تتلاشى؛ بلا كتابة.',
                 'L04': 'فقاعة رسالة بخطوط متموجة؛ أربع أيقونات (شخص، عدسة، ميزان بمجموعتين، كتب وسماعة)؛ بلا علامات استفهام ولا كتابة.'}
    for L in ['L01', 'L02', 'L04']:
        add(f'U11.{L}-title-boy.webp', [RB, RL], tb[L], chk_title[L])
        add(f'U11.{L}-title-girl.webp', [RG, RL], tg[L], 'كما في غلاف الولد.')
    # ———— U11.L01 ————
    add('U11.L01-exp.webp', [RB, RL], f"Experiment page: a 2×2 grid of four rounded cards on a cream background. (1) {BOY} sits calmly on a chair pressing two fingers gently on the inside of his wrist, looking at a simple round wall clock with only plain tick marks. (2) He jumps in place happily on a soft mat in an empty room, wearing sneakers. (3) Right after jumping he sits again, cheeks pink, a few sweat drops on his forehead, counting his pulse at the wrist, with a glass of water beside him. (4) A notebook with an empty table of blank boxes, a pencil, and a small strip of five pale-yellow to darker-yellow color squares (a urine-color chart, just colors). {LAM} holds a small stopwatch with no digits. MUST: no numbers on the clock or stopwatch; safe empty space for jumping; no text.", 'الساعة والمؤقّت بلا أرقام؛ قفز في مكان آمن؛ احمرار خفيف وعرق بعد القفز؛ جدول فارغ وشريط ألوان فقط.')
    add('U11.L01-letter.webp', [RL], f"Letter scene: a friendly cartoon heart character (simple realistic heart shape with a big kind face, NOT a ♥ symbol) sits at a small desk writing a letter with only wavy lines; around it, its team-mates wave happily as small friendly characters: two pink lungs holding hands, a small brain with a spark, a skin patch with tiny water-drop sweat beads, and two bean-shaped kidneys holding a water drop. {LAM} holds a small water bottle. MUST: friendly simple organs, no gore; the heart is not a valentine symbol; the letter has only wavy lines; no text.", 'القلب شخصية بشكل حقيقي مبسّط لا ♥؛ فريق الأعضاء يلوّح؛ الرسالة بلا كتابة.')
    add('U11.L01-life.webp', [RB, RL], f"Everyday-life scene at a school football match on a hot sunny day: a classmate sits on the grass looking pale and sweaty, holding his head; {BOY} has stopped the game, raising one hand to call the coach who is hurrying over; another child brings a water bottle, and two friends help the classmate toward the shade of a big tree. {LAM} holds an umbrella over the classmate. MUST: caring, calm mood; no one is lying unconscious; no blood; no text or numbers on shirts.", 'الزميل شاحب متعرق جالس لا فاقد الوعي؛ البطل يوقف اللعب ويطلب المدرب؛ ظل وماء؛ بلا أرقام على القمصان.')
    add('U11.L01-hist1.webp', [RL], f"Historical scene in a Copenhagen university physiology laboratory around 1919: a Danish scientist with round glasses, a neat moustache and a white lab coat over a dark suit looks into a brass microscope with delight; next to him a large round magnified-view bubble shows a network of thin branching capillaries, some filled dark (stained with black ink) and some pale; on the wooden bench: glass slides, a small bottle of black ink, notebooks with wavy lines. Tall windows show a northern European rooftop. {LAM} peeks into the eyepiece from the other side. MUST: no animals and no surgery visible; no text on the bottle or notebooks; gentle cartoon figure, not a portrait.", 'لا حيوانات ولا جراحة؛ فقاعة تكبير تُظهر شعيرات بعضها داكن مصبوغ؛ بلا كتابة على الزجاجة أو الدفاتر.')
    # ———— U11.L02 ————
    add('U11.L02-exp.webp', [RG, RL], f"Experiment page: a 2×2 grid of four rounded cards on a cream background. (1) {GIRL} sits upright on a chair breathing normally, calm. (2) She sits and gently pinches her nose while breathing through a plain drinking straw held in her lips, eyebrows slightly raised as it feels harder. (3) She has taken the straw away and breathes normally again, relaxed, giving a thumbs-up. (4) A notebook with an empty table of blank boxes and a pencil, and the straw lying beside it. {LAM} holds a small stopwatch with no digits. MUST: she is seated in every card; no smoke or cigarettes anywhere; no numbers; no text.", 'جالسة في كل البطاقات؛ ماصّة عادية؛ لا دخان ولا سجائر؛ مؤقّت بلا أرقام؛ بلا كتابة.')
    add('U11.L02-letter.webp', [RL], f"Letter scene: two friendly pink lung characters with big kind faces sit side by side on a cushion, writing a letter together with only wavy lines; tiny hair-like cilia on their airway wave like little brooms sweeping specks of dust away; a small simple realistic heart character (not a ♥ symbol) and a small brain character peek in happily from the side. Fresh green leaves and clean air swirls float around. {LAM} holds an open glove up in a 'no thanks' gesture. MUST: healthy pink lungs, not diseased; no cigarettes or smoke; the letter has only wavy lines; no text.", 'رئتان ورديتان سليمتان؛ الأهداب تكنس الغبار؛ لا سجائر ولا دخان؛ الرسالة بلا كتابة.')
    add('U11.L02-life.webp', [RB, RL], f"Everyday-life scene on a street on the way home from school: an older teenage boy leans on a wall and holds out a small plain pen-shaped device toward {BOY} (no vapor, no brand, no lights); {BOY} shakes his head and raises a calm open palm in a polite 'no, thanks', while walking away together with two smiling friends who carry school bags. {LAM} walks with them. MUST: no smoke or vapor anywhere; no cigarettes; the device is plain and small; the hero is clearly refusing and leaving; no text.", 'لا دخان ولا بخار ولا سجائر؛ الجهاز صغير عادي بلا علامة؛ البطل يرفض ويمشي مع أصدقائه؛ بلا كتابة.')
    add('U11.L02-hist1.webp', [RL], f"Historical scene in a London office around 1951: two British scientists in 1950s suits and ties — one older with round glasses and grey hair, one younger with dark hair — sit at a large wooden desk covered with neat stacks of paper questionnaires and envelopes; one opens an envelope while the other points at a large hand-drawn bar chart pinned to the wall with two groups of plain bars (no numbers, no labels). A filing cabinet and a window with a grey city view. {LAM} carries a small stack of envelopes. MUST: no cigarettes, no smoke, no ashtrays; no text or numbers on the papers or chart; gentle cartoon figures, not portraits.", 'لا سجائر ولا منافض؛ استبانات ورسائل؛ رسم أعمدة بلا أرقام ولا تسميات.')
    # ———— U11.L04 ————
    add('U11.L04-exp.webp', [RG, RL], f"Experiment page: a 2×2 grid of four rounded cards on a cream background. (1) {GIRL} and two classmates sit at a table with five blank message cards that show only wavy lines. (2) She holds up one card and a small hand-drawn card with four simple icons (a person, a magnifying glass, a balance scale, a book), thinking. (3) The children place the message cards into three trays colored green, red and yellow. (4) A notebook with an empty table of blank boxes and a pencil. {LAM} holds the yellow tray. MUST: no text or letters on any card or tray, only wavy lines and simple icons; no question marks.", 'بطاقات رسائل بخطوط متموجة؛ ثلاث صوانٍ أخضر وأحمر وأصفر؛ أيقونات بسيطة؛ بلا كتابة ولا علامات استفهام.')
    add('U11.L04-letter.webp', [RL], f"Letter scene: a friendly cartoon brain character with a big kind face and a small glowing light bulb above it sits at a desk writing a letter with only wavy lines; around it float small icons: a magnifying glass, a balance scale with two identical small groups, a book, and a little graduation cap. {LAM} sits on the desk listening happily. MUST: the letter has only wavy lines; no text, no question marks.", 'الدماغ شخصية لطيفة ومصباح؛ أيقونات العدسة والميزان والكتاب؛ الرسالة بلا كتابة.')
    add('U11.L04-life.webp', [RG, RL], f"Everyday-life scene in a family living room in the evening: a mother in a headscarf looks at her phone, which shows a message bubble with only wavy lines; an aunt beside her looks excited about the message; {GIRL} sits beside her mother and kindly suggests something, pointing to a small picture of a doctor with a stethoscope on a family photo shelf; the mother smiles and nods. {LAM} holds a magnifying lens over the phone. MUST: respectful, warm mood; no one is mocked; the phone shows only wavy lines; no text.", 'جو عائلي محترم؛ الهاتف بخطوط متموجة؛ البنت تقترح سؤال الطبيب بلطف؛ بلا كتابة.')
    add('U11.L04-hist1.webp', [RL], f"Historical scene in a bright hospital hall in Cairo around the year 1242 (a medieval bimaristan with horseshoe arches, patterned tiles and a small fountain): a thoughtful physician with a white turban and a short dark beard sits at a low wooden desk writing in a large book with a reed pen; on the open page is a simple line sketch of a heart with a solid wall in the middle and a curved arrow going up to two simple lungs and back; two young students sit nearby listening. {LAM} looks at the sketch through its lens. MUST: the book has no writing, only the simple sketch and wavy lines; no religious symbols on the walls; gentle cartoon figures, not portraits.", 'رسم قلب بجدار صلب وسهم إلى الرئتين وعودة؛ لا كتابة في الكتاب؛ أقواس بيمارستان؛ لا رموز دينية.')
    return P

if __name__ == '__main__':
    P = items()
    OUT.mkdir(parents=True, exist_ok=True)
    data = {'unit': 'U11', 'style': STYLE, 'negative': NEG,
            'pending_imagegen': {p['name']: {k: p[k] for k in ('lesson', 'refs', 'prompt', 'negative', 'check')} for p in P}}
    (OUT / 'prompts-final-imagegen.json').write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
    TT = {'title-boy': 'غلاف (ولد)', 'title-girl': 'غلاف (بنت)', 'exp': 'التجربة', 'letter': 'الرسالة', 'life': 'في حياتي', 'hist1': 'علماء 1'}
    md = [f'# برومبتات الصور القصصية — الوحدة U11 «قضايا التكامل» ({len(P)} صورة)', '',
          '**طريقة العمل:**',
          '1. لكل صورة: أرفق في أداة التوليد صور المرجع المذكورة (مرجع البطل والبطلة ولمّاح)، ثم الصق البرومبت كما هو؛ فيه وصف الأسلوب الموحّد في أوله.',
          '2. المقاس عمودي **1024×1536**. بلا أي كتابة أو أرقام داخل الصورة.',
          '3. احفظ كل صورة **بالاسم المكتوب فوقها بالضبط** (WebP أو PNG، وأنا أحوّل)، ثم أرسلها مضغوطة في ملف واحد أو أرفقها هنا.',
          '4. قبل أن تقبل الصورة، راجع سطر «تحقق» تحتها. وفي درس الدخان: لا سجائر ولا دخان في أي صورة.', '',
          f'**Negative prompt (إن كانت الأداة تقبله):** `{NEG}`', '']
    for i, p in enumerate(P, 1):
        slot = p['name'].split('-', 1)[1].replace('.webp', '')
        md += [f"## {i}. `{p['name']}` — {p['lesson']} {TT.get(slot, slot)}", f"**أرفق:** {'، '.join(p['refs'])}", '', '```', p['prompt'], '```', f"**تحقق:** {p['check']}", '']
    (OUT / 'الصور-القصصية-للنسخ.md').write_text('\n'.join(md), encoding='utf-8')
    print(len(P), 'برومبت')
